@spec mm_blob_serialise_spec  src=tests/specs/mm_blob_serialise_spec.lua  loc=403  sha=8bab28c  cases=18
@exercises midiBlob (midiBlob)
@surface   midiBlob.render, midiBlob.buildWire, midiBlob.parse, midiBlob.putKey, midiBlob.dropKey, midiBlob.repackKey

# Intent
  Round-trip pin for the write-path codec (inverse of parse).
  
  buildWire + render turn mm-shape records into a MIDI_SetAllEvts blob. The
  contract is parse(render(buildWire(x))) == x -- byte layout may reorder events
  that share a ppq, but the per-type record lists round-trip identically.
  Passthrough carries events parse doesn't model so a whole-take rewrite stays
  lossless.

# Helpers
  @fn grouped(texts)  @ 15-17
      -- buildWire wants texts grouped by rank; a fixture's texts are one flat list, and
      -- a parsed blob's sidecars come back indistinguishable from carried ones.
  @fn ser(notes, ccs, texts, passthrough, endPpq)  @ 21-23
      -- Most cases want bytes out of records, not the wire state in between; name the
      -- composition once so each case reads as the round trip it is testing.
  @fn tailPpq(blob)  @ 56-63
      -- The trailing all-notes-off marker carries the take length (EOT); endPpq
      -- places it past the last event so a whole-take rewrite never shrinks the take.
  @fn rankOf(kv)  @ 112
      -- A sidecar's key is a pure function of its owner's slot and ppq, which is what
      -- lets an incremental flush splice one in. Under the old dense text array an
      -- insert anywhere earlier renumbered every sidecar after it.
  @fn keysOfRank(wire, rank)  @ 114-120
  @fn key(ppq, rank, seq2)  @ 154
  @fn modelOf(notes, ccs, texts, passthrough)  @ 156-159
  @fn build(m)  @ 161
  @fn matchesRegen(wire, m, what)  @ 163-168
  @fn noteAt(ppq, pitch, vel)  @ 170-173
  @fn ccAt(ppq, code, val, shape)  @ 174-176
  @fn sidecarAt(ppq)  @ 177
  @fn noteKeys(notes, slot)  @ 179-182
  @fn indexOf(wire, kv)  @ 184-186

# Cases
  @case 'records survive serialise -> parse:  ..'  [pure]  @ 29-37
  @case 'unmodelled events round-trip through passthrough'  [pure]  @ 42-51
  @case 'colliding note onsets warn loudly and still serialise'  [pure]  @ 68-84
  @case 'endPpq positions the EOT tail; never shrinks past the last event'  [pure]  @ 88-94
  @case 'render twice over one wire yields identical bytes'  [pure]  @ 100-106
  @case 'note sidecar keys survive an insert at an earlier ppq'  [pure]  @ 123-145
  @case 'a slot far above the old band still keys and decodes as a note'  [pure]  @ 192-204
  @case 'putKey splices a note in, chunk for chunk with a full rebuild'  [pure]  @ 208-217
  @case 'a splice before the first key re-packs the successor delta'  [pure]  @ 221-233
  @case 'dropKey removes a note, the last key of the array included'  [pure]  @ 237-247
  @case 'a ppq move is a drop of both keys and a put of both'  [pure]  @ 251-263
  @case 'a length edit moves only the note-off key'  [pure]  @ 267-276
  @case 'repackKey rewrites the bytes under a key that has not moved'  [pure]  @ 280-288
  @case 'a bezier cc splices with its rider and loses it alone on a shape change'  [pure]  @ 292-307
  @case 'a wide cc splices as one chunks entry holding two events'  [pure]  @ 311-320
  @case 'a sidecar splices beside its owner on the owner\'s slot'  [pure]  @ 324-335
  @case 'the splice helpers refuse a kv the wire disagrees about, untouched'  [pure]  @ 341-354
  @case 'a storm of gestures splices to the same bytes as a full rebuild'  [pure]  @ 360-400

